//! Actions-only original Router/TLS/Common System IM receipt physical lifecycle.
use super::*;
use n::{account_test_support::TempDatabase,im_delivery::IncomingImDelivery,im_inbox::ImInboxScope,org_relation_inbox::OrgContext,relation_journal::RelationConfiguration};
fn original(temp:&TempDatabase,root:&str)->(AttemptOwner,Arc<n::account_runs::RunToken>){let line="app-account-0123456789abcdef0123456789abcdef";let mut c=n::account_config::tests::native_fixture(root,"127.0.0.1",1);c.credentials.sdk.expires_at_unix_seconds=None;c.profile.incoming=None;c.profile.client_ex=true;c.profile.native_receivers=Some(config(true));c.profile.org_relation_sync=Some(n::org_relation_sync::NativeOrgRelationSyncConfig{receive:true});temp.database.with_conn(|db|n::account_store::create(db,line,&c,100)).unwrap();let run=Arc::new(temp.database.with_conn(|c|n::account_runs::register_runtime(c,line,1,&n::account_runtime::local_nonce().unwrap())).unwrap());let mut session=n::session::HostingSession::new(line.into());session.import(n::tests::imported(),100).unwrap();(session.begin_login(100).unwrap(),run)}
fn packet()->Vec<u8>{let mut rel=Writer::new();rel.u32(1).unwrap();rel.bytes(b"private-remark").unwrap();rel.bytes(b"").unwrap();rel.properties(&[]).unwrap();let rel=rel.finish();let raw=n::im_data::ImMessage{index:7,time:123,sender_uid:b"private-sender",kind:b"System.OrgRelSync",content:b"private-content",attachments:vec![],parameters:vec![RpcProperty{key:b"GroupId",value:b"1-2"},RpcProperty{key:b"UpdateId",value:b"private-label"},RpcProperty{key:b"LastUpdateTime",value:b"0"},RpcProperty{key:b"UpdateTime",value:b"1"},RpcProperty{key:b"UpdateRel",value:rel.expose_to_transport()}]}.encode().unwrap();let mut w=Writer::versioned().unwrap();w.bytes(b"Message.MoreMessage").unwrap();w.properties(&[RpcProperty{key:b"Box",value:b"P2P/0_1"}]).unwrap();w.bytes(raw.expose_to_transport()).unwrap();let magic=91i32.to_be_bytes();let req=n::rpc_envelope::encode_request(91,&[RpcProperty{key:b"id",value:b"MessageReceiver"},RpcProperty{key:b"__magic",value:&magic}],n::rpc_incoming::ONLINE_MESSAGE_METHOD.as_bytes(),w.finish().expose_to_transport()).unwrap();let mut p=vec![0];p.extend_from_slice(req.expose_to_transport());p}
async fn org_auth(h:&RuntimeHandle,events:&mut mpsc::Receiver<RuntimeEvent>,who:&AttemptOwner,scope:&RpcConnectionScope){let p=NativeReceiverPolicy::capture(&config(true)).unwrap().with_org_relation_sync(n::org_relation_sync::NativeOrgRelationSyncConfig{receive:true}).unwrap();let cmd=h.command_handle();cmd.arm_native_receivers(who,scope,NativeReceiverSetup::capture(p,true,None).unwrap()).await.unwrap();authenticated(h,events,who,scope).await;cmd.configure_native_receivers(who,scope,7).await.unwrap();}
async fn next(events:&mut mpsc::Receiver<RuntimeEvent>,who:&AttemptOwner,scope:&RpcConnectionScope)->Box<IncomingImDelivery>{let e=bounded(events.recv()).await.unwrap();let mut values=e.into_events(who,scope).unwrap();assert_eq!(values.len(),1);let OfflineEvent::Im(e)=values.pop().unwrap()else{panic!("original system IM")};e}
fn commit(temp:&TempDatabase,run:Arc<n::account_runs::RunToken>,e:&IncomingImDelivery,gate:Arc<ImReceiptGate>)->n::im_inbox::CommittedIm{let cfg=Arc::new(temp.database.with_conn(|c|RelationConfiguration::capture(c,run.line_id(),run.revision(),Some(&e.scope()))).unwrap());let b=e.notice().binding().clone();let org=OrgContext::original(temp.database.clone(),run.clone(),b.clone(),gate.clone(),cfg).unwrap();ImInboxScope::original(run,b,gate).unwrap().with_org_context(Some(org)).unwrap().commit(&temp.database,e).unwrap().unwrap()}
fn rows(db:&crate::platform::db::Database)->i64{db.with_conn(|c|c.query_row("SELECT COUNT(*) FROM app_voice_org_relation_messages",[],|r|r.get(0)).map_err(|_|"fixture")).unwrap()}
#[tokio::test]async fn org_relation_io_positive_follows_original_sql_and_detached_proof_keeps_budget_through_logout_join(){Box::pin(async{let cert=Certificates::generate("IP:127.0.0.1");let listener=TcpListener::bind((std::net::Ipv4Addr::LOCALHOST,0)).await.unwrap();let route=router_policy(&cert.root,listener.local_addr().unwrap().port());let server=cert.server_config(&TLS13);let temp=TempDatabase::new();let(who,run)=original(&temp,&cert.root);let db=temp.database.clone();let(go,wait)=oneshot::channel();let peer=async move{let mut p=CommonPeer::open(listener,server).await;peer_login(&mut p).await;wait.await.unwrap();p.send(&[packet()]).await;let bytes=p.next().await.unwrap();assert_eq!(bytes[0],1);let r=n::rpc_envelope::decode_reply(&bytes[1..]).unwrap();assert_eq!(r.call_id,91);assert_eq!(r.result_stream,[0,1,0,0,0,0]);assert_eq!(rows(&db),1);peer_logout(&mut p).await;};let client=async{let conn=connected(&route,who.clone(),Instant::now()+Duration::from_secs(6)).await;let scope=conn.connection_scope();let(mut h,mut events)=conn.attach().unwrap();org_auth(&h,&mut events,&who,&scope).await;go.send(()).unwrap();let e=next(&mut events,&who,&scope).await;let p=commit(&temp,run,&e,ImReceiptGate::fresh());assert!(p.org_receipt());let receipt=bounded(h.command_handle().complete_im(&who,&scope,e.ticket(),Some(&p))).await.unwrap();assert!(receipt.matches(&who,&scope));assert!(bounded(h.logout(&who,&scope,&[])).await.unwrap().io_released());assert!(scope.native_rpc_resources().0>0);drop(e);drop(p);assert_eq!(scope.native_rpc_resources(),(0,0));};tokio::join!(Box::pin(bounded(peer)),Box::pin(bounded(client)));}).await;}
async fn partial(parent:bool){let cert=Certificates::generate("IP:127.0.0.1");let listener=TcpListener::bind((std::net::Ipv4Addr::LOCALHOST,0)).await.unwrap();let route=router_policy(&cert.root,listener.local_addr().unwrap().port());let server=cert.server_config(&TLS13);let temp=TempDatabase::new();let(who,run)=original(&temp,&cert.root);let(go,wait)=oneshot::channel();let peer=async move{let mut p=CommonPeer::open(listener,server).await;peer_login(&mut p).await;wait.await.unwrap();p.send(&[packet()]).await;while let Some(bytes)=p.next_input_only().await{assert!(matches!(bytes.as_slice(),[2]|[14]),"no complete retired system-control receipt or replay");}};let client=async{let mut conn=connected(&route,who.clone(),Instant::now()+Duration::from_secs(6)).await;let prefix=n::router_runtime::tests::auxiliary_io::AuxiliaryIoTest::original_unarmed(1);n::common_runtime::tests::gate_auxiliary_prefix(conn.common.as_mut().unwrap(),prefix.clone());let scope=conn.connection_scope();let(mut h,mut events)=conn.attach().unwrap();org_auth(&h,&mut events,&who,&scope).await;go.send(()).unwrap();let e=next(&mut events,&who,&scope).await;let gate=ImReceiptGate::fresh();let p=commit(&temp,run,&e,gate.clone());prefix.arm();let cmd=h.command_handle();let mut writing=Box::pin(cmd.complete_im(&who,&scope,e.ticket(),Some(&p)));tokio::select!{r=writing.as_mut()=>panic!("partial receipt cannot complete {r:?}"),_=bounded(prefix.paused())=>{}}assert_eq!(prefix.accepted.load(Ordering::SeqCst),1);if parent{gate.retire();assert_eq!(bounded(writing).await.err(),Some(RuntimeError::Cancelled));}else{drop(writing);}bounded(scope.closed()).await;let joined=bounded(h.close()).await;assert!(joined.io_released());assert_eq!(joined.reason,RuntimeError::Cancelled);assert!(prefix.dropped.load(Ordering::SeqCst));assert_eq!(prefix.accepted.load(Ordering::SeqCst),1);assert_eq!(rows(&temp.database),1);drop(e);drop(p);assert_eq!(scope.native_rpc_resources(),(0,0));};tokio::join!(Box::pin(bounded(peer)),Box::pin(bounded(client)));}
#[tokio::test]async fn org_relation_io_partial_ciphertext_parent_retirement_blocks_late_bytes_and_joins_same_fd(){Box::pin(partial(true)).await;}
#[tokio::test]async fn org_relation_io_partial_ciphertext_waiter_drop_does_not_refund_control_or_replay(){Box::pin(partial(false)).await;}
